-- Optional, offline-only queued origin inventory. No queued producer is enabled
-- by this schema; host currentness and native mutation authority are separate.
CREATE INDEX s04_queued_origin_account ON fm_v2_change_sets(json_extract(operation_metadata_json,'$.source.account_id'),change_set_id) WHERE reason='s04.queued-origin.v1' AND json_valid(operation_metadata_json);
CREATE INDEX s04_queued_origin_account_owner ON fm_v2_change_sets(json_extract(operation_metadata_json,'$.source.account_id'),owner_id,change_set_id) WHERE reason='s04.queued-origin.v1' AND json_valid(operation_metadata_json);
CREATE INDEX s04_queued_origin_chat ON fm_v2_change_sets(json_extract(operation_metadata_json,'$.source.account_id'),json_extract(operation_metadata_json,'$.source.chat_id'),change_set_id) WHERE reason='s04.queued-origin.v1' AND json_valid(operation_metadata_json);
CREATE INDEX s04_queued_origin_message ON fm_v2_change_sets(json_extract(operation_metadata_json,'$.source.account_id'),json_extract(operation_metadata_json,'$.source.chat_id'),json_extract(operation_metadata_json,'$.source.message_id'),change_set_id) WHERE reason='s04.queued-origin.v1' AND json_valid(operation_metadata_json);
CREATE INDEX s04_queued_origin_source ON fm_v2_change_sets(owner_id,source_event_id,change_set_id) WHERE reason='s04.queued-origin.v1';
CREATE INDEX s04_queued_any_change_source ON fm_v2_change_sets(owner_id,source_event_id,reason,change_set_id);
CREATE INDEX s04_queued_source_owner ON fm_v2_sources(owner_id,source_id,source_revision) WHERE source_type='host_queued_part.v1';
CREATE INDEX s04_queued_document_source ON fm_v2_documents(owner_id,source_id,source_revision);
CREATE INDEX s04_queued_episode_source ON fm_v2_episodes(owner_id,source_id,source_revision);
CREATE INDEX s04_queued_candidate_revision_source ON fm_v2_candidate_revisions(owner_id,source_id,source_revision,candidate_id,revision) WHERE source_id IS NOT NULL;
CREATE INDEX s04_queued_origin_owner_account ON fm_v2_change_sets(owner_id,json_extract(operation_metadata_json,'$.source.account_id'),change_set_id) WHERE reason='s04.queued-origin.v1' AND json_valid(operation_metadata_json);
CREATE INDEX s04_queued_origin_invalid ON fm_v2_change_sets(owner_id,change_set_id) WHERE reason='s04.queued-origin.v1' AND (NOT json_valid(operation_metadata_json) OR CASE WHEN json_valid(operation_metadata_json) THEN json_type(operation_metadata_json,'$.source.account_id') IS NOT 'text' OR length(json_extract(operation_metadata_json,'$.source.account_id')) NOT BETWEEN 1 AND 512 OR json_extract(operation_metadata_json,'$.source.account_id')!=trim(json_extract(operation_metadata_json,'$.source.account_id')) ELSE 0 END);
CREATE INDEX s04_queued_invalid_location ON fm_v2_change_sets(owner_id,json_extract(operation_metadata_json,'$.source.account_id'),change_set_id) WHERE reason='s04.queued-origin.v1' AND json_valid(operation_metadata_json) AND (json_type(operation_metadata_json,'$.source.chat_id') IS NOT 'text' OR length(json_extract(operation_metadata_json,'$.source.chat_id')) NOT BETWEEN 1 AND 512 OR json_extract(operation_metadata_json,'$.source.chat_id') GLOB '*[^!-~]*' OR json_type(operation_metadata_json,'$.source.message_id') IS NOT 'text' OR length(json_extract(operation_metadata_json,'$.source.message_id')) NOT BETWEEN 1 AND 512 OR json_extract(operation_metadata_json,'$.source.message_id') GLOB '*[^!-~]*');
CREATE INDEX s04_queued_rebind_origin ON fm_v2_change_sets(owner_id,json_extract(operation_metadata_json,'$.origin_id'),change_set_id) WHERE reason='s04.queued-rebind.v1' AND json_valid(operation_metadata_json);
CREATE INDEX s04_queued_rebind_prior ON fm_v2_change_sets(owner_id,json_extract(operation_metadata_json,'$.origin_id'),json_extract(operation_metadata_json,'$.prior_receipt_id'),change_set_id) WHERE reason='s04.queued-rebind.v1' AND json_valid(operation_metadata_json);
CREATE INDEX s04_queued_rebind_invalid ON fm_v2_change_sets(owner_id,change_set_id) WHERE reason='s04.queued-rebind.v1' AND (NOT json_valid(operation_metadata_json) OR CASE WHEN json_valid(operation_metadata_json) THEN json_type(operation_metadata_json,'$.origin_id') IS NOT 'text' OR length(json_extract(operation_metadata_json,'$.origin_id'))!=77 OR substr(json_extract(operation_metadata_json,'$.origin_id'),1,13)!='cs_s04queued_' OR substr(json_extract(operation_metadata_json,'$.origin_id'),14) GLOB '*[^0-9a-f]*' OR (json_type(operation_metadata_json,'$.prior_receipt_id')='text' AND (length(json_extract(operation_metadata_json,'$.prior_receipt_id'))!=78 OR substr(json_extract(operation_metadata_json,'$.prior_receipt_id'),1,14)!='cs_s04qrebind_' OR substr(json_extract(operation_metadata_json,'$.prior_receipt_id'),15) GLOB '*[^0-9a-f]*')) OR (json_type(operation_metadata_json,'$.prior_receipt_hash')='text' AND (length(json_extract(operation_metadata_json,'$.prior_receipt_hash'))!=64 OR json_extract(operation_metadata_json,'$.prior_receipt_hash') GLOB '*[^0-9a-f]*')) OR (json_type(operation_metadata_json,'$.prior_receipt_id') IS NOT 'text' AND json_type(operation_metadata_json,'$.prior_receipt_id') IS NOT 'null') OR (json_type(operation_metadata_json,'$.prior_receipt_hash') IS NOT 'text' AND json_type(operation_metadata_json,'$.prior_receipt_hash') IS NOT 'null') OR (json_type(operation_metadata_json,'$.prior_receipt_id')='null')!=(json_type(operation_metadata_json,'$.prior_receipt_hash')='null') ELSE 0 END);
CREATE TRIGGER s04_queued_source_insert BEFORE INSERT ON fm_v2_sources WHEN NEW.source_type='host_queued_part.v1' AND fm_queued_source_capability() IS NOT 'openclank.queued_source.writer.v1' BEGIN SELECT RAISE(ABORT,'queued source writer required'); END;
CREATE TRIGGER s04_queued_source_update BEFORE UPDATE ON fm_v2_sources WHEN (OLD.source_type='host_queued_part.v1' OR NEW.source_type='host_queued_part.v1') AND fm_queued_source_capability() IS NOT 'openclank.queued_source.writer.v1' BEGIN SELECT RAISE(ABORT,'queued source writer required'); END;
CREATE TRIGGER s04_queued_source_delete BEFORE DELETE ON fm_v2_sources WHEN OLD.source_type='host_queued_part.v1' AND fm_queued_source_capability() IS NOT 'openclank.queued_source.writer.v1' BEGIN SELECT RAISE(ABORT,'queued source writer required'); END;
